void solve(vector<int>& nums, vector<int>& curr, vector<bool>& visited, vector<vector<int>>& ans) {
    if (curr.size() == nums.size()) {
        ans.push_back(curr);
        return;
    }
    for (int i = 0; i < nums.size(); i++) {
        if (!visited[i]) {
            visited[i] = true;
            curr.push_back(nums[i]);
            solve(nums, curr, visited, ans);
            curr.pop_back();
            visited[i] = false;
        }
    }
}

