def permute(nums):
    ans = []
    visited = [False] * len(nums)
    def solve(curr):
        if len(curr) == len(nums):
            ans.append(curr[:])
            return
        for i in range(len(nums)):
            if not visited[i]:
                visited[i] = True
                curr.append(nums[i])
                solve(curr)
                curr.pop()
                visited[i] = False
    solve([])
    return ans

