    if(idx == arr.size()) {
        if(target == 0) ans.push_back(curr);
        return;
    }
    if(arr[idx] <= target) {
        curr.push_back(arr[idx]);
        solve(idx, target - arr[idx], arr, curr, ans);
        curr.pop_back();
    }
    solve(idx + 1, target, arr, curr, ans);
}

