def combinationSum(candidates, target):
    ans = []
    def solve(idx, target, curr):
        if idx == len(candidates):
            if target == 0:
                ans.append(curr[:])
            return
        if candidates[idx] <= target:
            curr.append(candidates[idx])
            solve(idx, target - candidates[idx], curr)
            curr.pop()
        solve(idx + 1, target, curr)
    solve(0, target, [])
    return ans

