def partition(s):
    def isPal(s):
        return s == s[::-1]
    ans = []
    def solve(idx, curr):
        if idx == len(s):
            ans.append(curr[:])
            return
        for i in range(idx, len(s)):
            sub = s[idx:i+1]
            if isPal(sub):
                curr.append(sub)
                solve(i+1, curr)
                curr.pop()
    solve(0, [])
    return ans

