bool dfs(int r, int c, int idx, vector<vector<char>>& board, string& word) {
    if (idx == word.length()) return true;
    if (r < 0 || r >= board.size() || c < 0 || c >= board[0].size() || board[r][c] != word[idx]) return false;
    char temp = board[r][c];
    board[r][c] = '#';
    bool found = dfs(r+1, c, idx+1, board, word) || dfs(r-1, c, idx+1, board, word) || 
                 dfs(r, c+1, idx+1, board, word) || dfs(r, c-1, idx+1, board, word);
    board[r][c] = temp;
    return found;
}
