bool isSafe(int node, vector<int> adj[], vector<int>& color, int n, int col) {
    for (int neighbor : adj[node]) {
        if (color[neighbor] == col) return false;
    }
    return true;
}
bool solve(int node, vector<int> adj[], vector<int>& color, int n, int m) {
    if (node == n) return true;
    for (int i = 1; i <= m; i++) {
        if (isSafe(node, adj, color, n, i)) {
            color[node] = i;
            if (solve(node + 1, adj, color, n, m)) return true;
            color[node] = 0;
        }
    }
    return false;
}

