def restoreIpAddresses(s):
    ans = []
    def solve(idx, path):
        if len(path) == 4:
            if idx == len(s):
                ans.append('.'.join(path))
            return
        for length in range(1, 4):
            if idx + length <= len(s):
                sub = s[idx:idx+length]
                if (sub[0] == '0' and len(sub) > 1) or int(sub) > 255:
                    continue
                path.append(sub)
                solve(idx + length, path)
                path.pop()
    solve(0, [])
    return ans

