def countArrangement(n):
    visited = [False] * (n + 1)
    res = [0]
    def solve(idx):
        if idx > n:
            res[0] += 1
            return
        for i in range(1, n + 1):
            if not visited[i] and (i % idx == 0 or idx % i == 0):
                visited[i] = True
                solve(idx + 1)
                visited[i] = False
    solve(1)
    return res[0]
